/** Splits each dotted path into nested packages, sharing every ancestor already seen. */
function buildTree(records: FlatModule[]): ModuleNode {
  const root: ModuleNode = { name: 'gallery', children: [] };
  const byPath = new Map<string, ModuleNode>([[root.name, root]]);

  for (const record of records) {
    const parts = record.name.split('.');
    let parent = root;
    for (let depth = 1; depth < parts.length; depth++) {
      const path = parts.slice(0, depth + 1).join('.');
      let node = byPath.get(path);
      if (!node) {
        node = { name: parts[depth] };
        byPath.set(path, node);
        (parent.children ??= []).push(node);
      }
      parent = node;
    }
    parent.imports = record.imports;
  }
  return root;
}

const moduleTree: ModuleNode = buildTree(modules);

type Node = d3.HierarchyPointNode<ModuleNode>;
type Edge = { key: string; group: string; nodes: Node[] };

/** Radial band reserved outside the layout for the leaf labels. */
const LABEL_ROOM = 108;
const FONT_SIZE = 10;
/** Mean advance width of 10px sans-serif, used to drop labels that would overflow. */
const CHAR_WIDTH = 5.6;
const LABEL_GAP = 6;
const GROUPS = ['viz', 'core', 'ui'];

/** A tree whose leaves name the leaves they import, plus the top-level group names to colour by. */
export type Data = { tree: ModuleNode; groups: string[] };

const DEMO: Data = { tree: moduleTree, groups: GROUPS };

function idOf(node: Node): string {
  return `${node.parent ? `${idOf(node.parent)}.` : ''}${node.data.name}`;
}

/** Name of the depth-1 package a node belongs to; drives the categorical color. */
function groupOf(node: Node): string {
  let current = node;
  while (current.depth > 1 && current.parent) current = current.parent;
  return current.data.name;
}

export default function HierarchicalEdgeBundling({ data = DEMO, width }:
  { data?: Data; width: number }) {
  const height = width;
  const radius = width / 2;
  const innerRadius = Math.max(radius - LABEL_ROOM, 20);

  const { leaves, edges } = useMemo(() => {
    const hierarchy = d3
      .hierarchy(data.tree)
      .sort(
        (a, b) =>
          d3.ascending(a.height, b.height) || d3.ascending(a.data.name, b.data.name)
      );
    const root = d3.cluster<ModuleNode>().size([2 * Math.PI, innerRadius])(hierarchy);
    const nodes = root.leaves();
    const byId = new Map(nodes.map((leaf) => [idOf(leaf), leaf]));

    // Each edge is routed through its two endpoints' least common ancestor.
    const routed = nodes.flatMap((source) =>
      (source.data.imports ?? []).flatMap((importId) => {
        const target = byId.get(importId);
        if (!target) return [];
        return [
          { key: `${idOf(source)}>${importId}`, group: groupOf(source), nodes: source.path(target) }
        ];
      })
    );
    const edges: Edge[] = routed;
    return { leaves: nodes, edges };
  }, [data, innerRadius]);

  const line = useMemo(
    () =>
      d3
        .lineRadial<Node>()
        .curve(d3.curveBundle.beta(0.85))
        .radius((d) => d.y)
        .angle((d) => d.x),
    []
  );

  const color = useMemo(
    () => d3.scaleOrdinal<string, string>(data.groups, d3.schemeObservable10),
    [data]
  );

  const labelRoom = radius - innerRadius - LABEL_GAP * 2;

  if (width === 0) return null;

  return (
    <svg
      viewBox={`${-radius} ${-radius} ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Hierarchical edge bundling of imports between modules of a charting library"
    >
      <g fill="none">
        {edges.map((edge) => (
          <path
            key={edge.key}
            d={line(edge.nodes) ?? undefined}
            stroke={color(edge.group)}
            strokeOpacity={0.35}
            style={{ mixBlendMode: 'screen' }}
          />
        ))}
      </g>
      <g fontSize={FONT_SIZE}>
        {leaves.map((leaf) => {
          const flipped = leaf.x >= Math.PI;
          const fits = leaf.data.name.length * CHAR_WIDTH < labelRoom;
          return (
            <g
              key={idOf(leaf)}
              transform={`rotate(${(leaf.x * 180) / Math.PI - 90}) translate(${leaf.y},0)`}
            >
              <title>{idOf(leaf)}</title>
              <circle r={2} fill={color(groupOf(leaf))} />
              {fits && (
                <text
                  dy="0.31em"
                  x={flipped ? -LABEL_GAP : LABEL_GAP}
                  textAnchor={flipped ? 'end' : 'start'}
                  transform={flipped ? 'rotate(180)' : undefined}
                  fill="var(--text)"
                >
                  {leaf.data.name}
                </text>
              )}
            </g>
          );
        })}
      </g>
    </svg>
  );
}
